-- A future evaluator should assert the tasks table remains readable.
SELECT id, title FROM tasks LIMIT 0;

-- Read-only contract: verify the non-null priority column is present and selectable.
SELECT priority FROM tasks LIMIT 0;

CREATE TABLE tasks (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 0
);
